  const emailBodyHtml = email.html || '';
  const fullBody = emailBody + ' ' + emailBodyHtml;
  const headers = email.payload?.headers || email.headers || [];
  let headerFrom = '';
  for (const h of headers) {
    if (h.name?.toLowerCase() === 'from' || h.name?.toLowerCase() === 'x-original-from') {
      headerFrom += ' ' + (h.value || '');
