for (const item of items) {
  const msg = item.json;
  const messageId = msg.id;
  const payload = msg.payload || {};
  const parts = payload.parts || [];

  let pdfAttachment = null;

  function findPdf(parts) {
    for (const part of parts) {
      if (part.mimeType === 'application/pdf' && part.body?.attachmentId) {
        pdfAttachment = {
          filename: part.filename,
          attachmentId: part.body.attachmentId,
          size: part.body.size
        };
        return;
      }
      if (part.parts) findPdf(part.parts);
    }
  }

  findPdf(parts);

  const headers = payload.headers || [];
  const subjectHeader = headers.find(h => h.name.toLowerCase() === 'subject');
  const dateHeader = headers.find(h => h.name.toLowerCase() === 'date');

  if (pdfAttachment) {
    results.push({
      json: {
        message_id: messageId,
        subject: subjectHeader?.value || 'unknown',
        email_date: dateHeader?.value || '',
        pdf_filename: pdfAttachment.filename,
        pdf_attachment_id: pdfAttachment.attachmentId,
        pdf_size: pdfAttachment.size
      }
    });
  }
}

return results;

// Convert Gmail's URL-safe base64 to binary
const items = $input.all();
const pdfInfo = $('Find PDF Attachment').first().json;

for (const item of items) {
  let base64Data = item.json.data || '';

  // Gmail uses URL-safe base64 - convert to standard
  base64Data = base64Data.replace(/-/g, '+').replace(/_/g, '/');

  // Add padding if needed
  while (base64Data.length % 4) {
    base64Data += '=';
  }

  return [{
    json: {
      message_id: pdfInfo.message_id,
      subject: pdfInfo.subject,
      email_date: pdfInfo.email_date,
      pdf_filename: pdfInfo.pdf_filename
    },
    binary: {
      data: {
        data: base64Data,
        mimeType: 'application/pdf',
        fileName: pdfInfo.pdf_filename || 'traffic.pdf',
        fileExtension: 'pdf'
      }
    }
  }];
}

const text =
  items[0].json.text ||
  items[0].json.text_preview ||
  "";

const lines = text.split(/\r?\n/);
const results = [];

// Extract the "through" date from PDF content
// Look for patterns like "Through January 12, 2026" or "thru 01/12/2026" etc.
let dataDate = "";
const throughMatch = text.match(/(?:through|thru)\s+([A-Za-z]+\s+\d{1,2},?\s+\d{4}|\d{1,2}\/\d{1,2}\/\d{2,4})/i);
if (throughMatch) {
  dataDate = throughMatch[1].trim();
} else {
  // Fallback: look for any date pattern in first few lines
  const dateMatch = text.match(/\b(\d{1,2}\/\d{1,2}\/\d{2,4}|[A-Za-z]+\s+\d{1,2},?\s+\d{4})\b/);
  if (dateMatch) {
    dataDate = dateMatch[1].trim();
  }
}

for (const line of lines) {
  // Only real store rows
  if (!/^[0-9A-Z]+:/.test(line.trim())) continue;

  // Example:
  // 6ESH: Chisholm Trail 7.81% 50.00 640.00 19.00 15.00 11.00

  const parts = line.trim().split(/\s+/);

  // Drop store code (e.g. "6ESH:")
  parts.shift();

  // Pop values from right
  parts.pop(); // accessory
  parts.pop(); // upgrade
  parts.pop(); // add-a-line
  const exitTraffic = parts.pop(); // ← keep this
  parts.pop(); // interactions
  parts.pop(); // conversion

  const storeName = parts.join(" ");

  results.push({
    json: {
      store: storeName,
      exitTraffic: exitTraffic.replace(/,/g, ""),
      dataDate: dataDate
    }
  });
}

return results;

